package bank;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class Interest {
    public static BigDecimal calculate(BigDecimal principal, int ratePercent) {
        return principal.multiply(BigDecimal.valueOf(ratePercent))
                .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
    }

    public static void main(String[] args) {
        BigDecimal principal = new BigDecimal(args[0]);
        int rate = Integer.parseInt(args[1]);
        BigDecimal earned = calculate(principal, rate);
        System.out.println("Interest for " + principal.toPlainString() + " at " + rate + "%: " + earned);
        System.out.println("Rounded to " + earned.scale() + " decimal places.");
    }
}

