package web;

import java.time.Instant;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;

public final class SessionStore {
    private final Map<String, Instant> expirations = new LinkedHashMap<>();

    public void put(String id, Instant expiresAt) {
        expirations.put(id, expiresAt);
    }

    public int removeExpired(Instant now) {
        int removed = 0;
        Iterator<Map.Entry<String, Instant>> iterator = expirations.entrySet().iterator();
        while (iterator.hasNext()) {
            Map.Entry<String, Instant> entry = iterator.next();
            if (!entry.getValue().isAfter(now)) {
                iterator.remove();
                removed++;
            }
        }
        return removed;
    }

    public int size() {
        return expirations.size();
    }
}

