#include "opcodes.h"
#include <stddef.h>

typedef struct {
    uint8_t code;
    const char *name;
} Opcode;

static const Opcode opcodes[] = {
    {0x06, "LD B,d8"},
    {0x18, "JR r"},
    {0x31, "LD SP,d16"},
    {0xAF, "XOR A"},
};

const char *opcode_name(uint8_t code) {
    size_t low = 0;
    size_t high = sizeof(opcodes) / sizeof(opcodes[0]);

    while (low < high) {
        size_t middle = low + (high - low) / 2;
        if (opcodes[middle].code < code) {
            low = middle + 1;
        } else {
            high = middle - 1;
        }
    }

    if (low < sizeof(opcodes) / sizeof(opcodes[0]) &&
        opcodes[low].code == code) {
        return opcodes[low].name;
    }
    return NULL;
}

