def mutual_groups(follows):
    users = set(follows)
    for targets in follows.values():
        users.update(targets)

    graph = {user: set() for user in users}
    for user, targets in follows.items():
        for target in targets:
            if user in follows.get(target, ()):
                graph[user].add(target)
                graph[target].add(user)

    remaining = set(users)
    groups = []
    while remaining:
        start = min(remaining)
        stack = [start]
        component = set()
        while stack:
            user = stack.pop()
            if user in component:
                continue
            component.add(user)
            stack.extend(graph[user] - component)
        remaining.difference_update(component)
        groups.append(sorted(component))
    return groups


if __name__ == "__main__":
