import sys

DENOMINATIONS = (50000, 20000, 10000, 5000, 2000, 1000, 500, 200, 100, 50, 20, 10, 5, 2, 1)


def make_change(due_cents: int, paid_cents: int) -> dict[int, int]:
    if due_cents < 0 or paid_cents < due_cents:
        raise ValueError("payment must cover a nonnegative amount due")
    remaining = paid_cents - due_cents
    result = {}
    for denomination in DENOMINATIONS:
        count, remaining = divmod(remaining, denomination)
        if count:
            result[denomination] = count
    return result


if __name__ == "__main__":
    due, paid = map(int, sys.argv[1:3])
    breakdown = make_change(due, paid)
    print(", ".join(f"{denomination}: {count}" for denomination, count in breakdown.items()))

