export type State = { items: string[]; query: string };
export type Action =
  | { type: "add"; item: string }
  | { type: "setQuery"; value: string }
  | { type: "clear" };

type HandlerMap = {
  [K in Action["type"]]: (state: State, action: Extract<Action, { type: K }>) => State;
};

const handlers: HandlerMap = {
  add: (state, action) => ({ ...state, items: [...state.items, action.item] }),
  setQuery: (state, action) => ({ ...state, query: action.value }),
  clear: (state) => ({ ...state, items: [] }),
};

export function reducer(state: State, action: Action): State {
  return handlers[action.type](state, action as never);
}

